// CBSE 12 Mathematics ch03 Matrices — practice bank with independent re-solve checks.
// Givens are shared constants; every authored answer is typed as a literal (array or text) and the
// check recomputes it from the givens with src/mat.mjs (products, transposes, inverses by A·B = I).
import { Q, caseQ, child, mk, r } from '../../cbse-12-mathematics-ch01/src/lib.mjs';
import { mul, add, sub, scal, T, I, O, eqM, pow, isSym, isSkew, isInverse, sum, flat, fromRule, bm } from './mat.mjs';

const $ = (A) => `$${bm(A)}$`;
const divisorsCount = (n) => [...Array(n).keys()].map((k) => k + 1).filter((d) => n % d === 0).length;

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: 'A matrix with 3 rows and 4 columns has order', opts: [r`$3 \times 4$`, r`$4 \times 3$`, '$12$', '$7$'], key: 'a', sol: r`Order is written (number of rows) $\times$ (number of columns), so it is $3 \times 4$. It has $12$ elements, but $12$ is not its order.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => { const A = O(3, 4); C.which(['3x4', '4x3', '12', '7'], `${A.length}x${A[0].length}`); });
Q('m02', mk.mcq({ stem: 'A matrix has exactly 12 elements. How many different orders can it have?', opts: ['$6$', '$4$', '$3$', '$12$'], key: 'a', sol: r`An $m \times n$ matrix has $mn$ elements, so $mn = 12$: $1 \times 12$, $12 \times 1$, $2 \times 6$, $6 \times 2$, $3 \times 4$, $4 \times 3$. That is $6$ orders (one for each divisor of $12$).`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which([6, 4, 3, 12], divisorsCount(12)));
Q('m03', mk.mcq({ stem: r`The matrix $\begin{bmatrix} 4 & 0 \\ 0 & 4 \end{bmatrix}$ is best described as`, opts: ['a scalar matrix', 'an identity matrix', 'a zero matrix', 'a row matrix'], key: 'a', sol: r`It is square, its off-diagonal elements are $0$ and its diagonal elements are equal ($4$), so it is a scalar matrix, $4I$. It is not the identity matrix because the diagonal elements are not $1$.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => { C.assert(eqM([[4, 0], [0, 4]], scal(4, I(2))) && !eqM([[4, 0], [0, 4]], I(2)), 'scalar 4I, not I'); C.key('a'); });
Q('m04', mk.mcq({ stem: r`A $2 \times 3$ matrix $A = [a_{ij}]$ has $a_{ij} = 2i - j$. The element $a_{23}$ is`, opts: ['$1$', '$4$', '$-4$', '$3$'], key: 'a', sol: r`$a_{23}$ is in row $i = 2$, column $j = 3$: $a_{23} = 2(2) - 3 = 1$. Option (b) uses $i = 3$, $j = 2$, which does not even exist in a $2 \times 3$ matrix.`, d: 2, c: 'understanding', t: [1], time: 45 }), (C) => { const A = fromRule(2, 3, (i, j) => 2 * i - j); C.which([1, 4, -4, 3], A[1][2]); });
Q('m05', mk.mcq({ stem: r`If $\begin{bmatrix} x + y & 3 \\ 1 & x - y \end{bmatrix} = \begin{bmatrix} 7 & 3 \\ 1 & 1 \end{bmatrix}$, then`, opts: ['$x = 4,\\ y = 3$', '$x = 3,\\ y = 4$', '$x = 7,\\ y = 1$', '$x = 5,\\ y = 2$'], key: 'a', sol: r`Equal matrices have equal corresponding elements: $x + y = 7$ and $x - y = 1$. Adding, $2x = 8$, so $x = 4$ and $y = 3$.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { const cands = [[4, 3], [3, 4], [7, 1], [5, 2]]; C.which(cands.map(([x, y]) => x + y === 7 && x - y === 1), true); });
Q('m06', mk.mcq({ stem: r`If $A$ is a $2 \times 3$ matrix and $B$ is a $3 \times 4$ matrix, then $AB$ is`, opts: [r`of order $2 \times 4$`, r`of order $3 \times 3$`, r`of order $4 \times 2$`, 'not defined'], key: 'a', sol: r`$AB$ is defined because $A$ has $3$ columns and $B$ has $3$ rows. The product takes the rows of $A$ and the columns of $B$: order $2 \times 4$.`, d: 1, c: 'recall', t: [2], time: 30 }), (C) => { const P = mul(O(2, 3), O(3, 4)); C.which(['2x4', '3x3', '4x2', 'undefined'], `${P.length}x${P[0].length}`); });
Q('m07', mk.mcq({ stem: r`$\begin{bmatrix} 1 & 2 \end{bmatrix}\begin{bmatrix} 3 \\ -1 \end{bmatrix}$ equals`, opts: [r`$\begin{bmatrix} 1 \end{bmatrix}$`, r`$\begin{bmatrix} 3 & -2 \end{bmatrix}$`, r`$\begin{bmatrix} 3 & 6 \\ -1 & -2 \end{bmatrix}$`, r`$\begin{bmatrix} 5 \end{bmatrix}$`], key: 'a', sol: r`A $1 \times 2$ matrix times a $2 \times 1$ matrix is $1 \times 1$: $1(3) + 2(-1) = 1$. Option (c) is the product in the other order, column times row.`, d: 2, c: 'understanding', t: [2], time: 45 }), (C) => { C.which([[1], [3, -2], [3, 6, -1, -2], [5]], flat(mul([[1, 2]], [[3], [-1]]))); C.assert(eqM(mul([[3], [-1]], [[1, 2]]), [[3, 6], [-1, -2]]), 'option (c) is the reverse product'); });
const A08 = [[2, 1], [0, 3]];
Q('m08', mk.mcq({ stem: r`If $A = ${bm(A08)}$, then $A^2$ is`, opts: [r`$\begin{bmatrix} 4 & 5 \\ 0 & 9 \end{bmatrix}$`, r`$\begin{bmatrix} 4 & 1 \\ 0 & 9 \end{bmatrix}$`, r`$\begin{bmatrix} 4 & 2 \\ 0 & 6 \end{bmatrix}$`, r`$\begin{bmatrix} 4 & 3 \\ 0 & 9 \end{bmatrix}$`], key: 'a', sol: r`Row 1 times column 2: $2(1) + 1(3) = 5$; the other entries are $4$, $0$, $9$. Option (b) squares each entry, which is not matrix multiplication; option (c) is $2A$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => C.which([[4, 5, 0, 9], [4, 1, 0, 9], [4, 2, 0, 6], [4, 3, 0, 9]], flat(mul(A08, A08))));
Q('m09', mk.mcq({ stem: 'For any two square matrices A and B of the same order, which statement is always true?', opts: ['$A + B = B + A$', '$AB = BA$', '$(A + B)^2 = A^2 + 2AB + B^2$', r`$AB = O$ implies $A = O$ or $B = O$`], key: 'a', sol: r`Matrix addition is commutative because it adds corresponding elements. Multiplication is not commutative, so $(A + B)^2 = A^2 + AB + BA + B^2$, which need not equal $A^2 + 2AB + B^2$; and two non-zero matrices can have a zero product.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => {
  const A = [[1, 2], [0, 1]], B = [[1, 0], [3, 1]];
  C.assert(!eqM(mul(A, B), mul(B, A)), 'AB != BA for a pair');
  const S = add(A, B);
  C.assert(!eqM(mul(S, S), add(add(mul(A, A), scal(2, mul(A, B))), mul(B, B))), '(A+B)^2 identity fails');
  C.assert(eqM(mul([[1, 1], [2, 2]], [[1, -1], [-1, 1]]), O(2)), 'non-zero matrices with zero product');
  C.assert(eqM(add(A, B), add(B, A)), 'addition commutes'); C.key('a');
});
const A10 = [[2, 2], [2, 2]];
Q('m10', mk.mcq({ stem: r`If $A = ${bm(A10)}$ and $A^2 = kA$, then $k$ equals`, opts: ['$4$', '$2$', '$8$', '$16$'], key: 'a', sol: r`$A^2 = \begin{bmatrix} 8 & 8 \\ 8 & 8 \end{bmatrix} = 4A$, so $k = 4$. Option (c) is an entry of $A^2$, not the multiplier.`, d: 3, c: 'application', t: [2], time: 60 }), (C) => { const A2 = mul(A10, A10); C.which([4, 2, 8, 16].map((k) => eqM(A2, scal(k, A10))), true); C.sol([8]); });
const A11 = [[0, 1], [-1, 0]];
Q('m11', mk.mcq({ stem: r`If $A = ${bm(A11)}$, then $A^4$ equals`, opts: ['$I$', '$-I$', '$A$', '$O$'], key: 'a', sol: r`$A^2 = \begin{bmatrix} -1 & 0 \\ 0 & -1 \end{bmatrix} = -I$, so $A^4 = (A^2)^2 = (-I)^2 = I$.`, d: 3, c: 'application', t: [2], time: 75 }), (C) => { const A4 = pow(A11, 4); C.which([I(2), scal(-1, I(2)), A11, O(2)].map((M) => eqM(M, A4)), true); C.assert(eqM(mul(A11, A11), scal(-1, I(2))), 'A^2 = -I'); });
Q('m12', mk.mcq({ stem: r`For matrices $A$ and $B$ for which $AB$ is defined, $(AB)^T$ equals`, opts: ['$B^TA^T$', '$A^TB^T$', '$AB$', '$BA$'], key: 'a', sol: r`The reversal law: the transpose of a product is the product of the transposes in the reverse order, $(AB)^T = B^TA^T$. In general $A^TB^T$ is different and may not even be defined.`, d: 1, c: 'recall', t: [3], time: 30 }), (C) => { const A = [[1, 2], [3, 4]], B = [[0, 1], [5, -2]]; const L = T(mul(A, B)); C.which([mul(T(B), T(A)), mul(T(A), T(B)), mul(A, B), mul(B, A)].map((M) => eqM(M, L)), true); });
Q('m13', mk.mcq({ stem: 'The diagonal elements of a skew-symmetric matrix are', opts: ['all zero', 'all equal to 1', 'equal to each other but non-zero', 'any real numbers'], key: 'a', sol: r`Skew-symmetric means $a_{ji} = -a_{ij}$ for all $i$, $j$. With $j = i$: $a_{ii} = -a_{ii}$, so $2a_{ii} = 0$ and $a_{ii} = 0$.`, d: 2, c: 'understanding', t: [3], time: 45 }), (C) => { const K = [[0, 3, -1], [-3, 0, 2], [1, -2, 0]]; C.assert(isSkew(K) && K.every((row, i) => row[i] === 0), 'skew example has zero diagonal'); C.key('a'); });
const skew14 = (x) => [[0, 3, -2], [x, 0, 5], [2, -5, 0]];
Q('m14', mk.mcq({ stem: r`The matrix $\begin{bmatrix} 0 & 3 & -2 \\ x & 0 & 5 \\ 2 & -5 & 0 \end{bmatrix}$ is skew-symmetric when $x$ equals`, opts: ['$-3$', '$3$', '$0$', '$5$'], key: 'a', sol: r`Skew-symmetric needs $a_{21} = -a_{12}$, so $x = -3$. The other pairs already satisfy the condition: $a_{31} = 2 = -(-2)$ and $a_{32} = -5 = -5$, and the diagonal is zero.`, d: 2, c: 'understanding', t: [3], time: 45 }), (C) => C.which([-3, 3, 0, 5].map((x) => isSkew(skew14(x))), true));
const A15 = [[3, 5], [1, -2]];
Q('m15', mk.mcq({ stem: r`For $A = ${bm(A15)}$, the symmetric matrix $\dfrac12(A + A^T)$ is`, opts: [r`$\begin{bmatrix} 3 & 3 \\ 3 & -2 \end{bmatrix}$`, r`$\begin{bmatrix} 0 & 2 \\ -2 & 0 \end{bmatrix}$`, r`$\begin{bmatrix} 6 & 6 \\ 6 & -4 \end{bmatrix}$`, r`$\begin{bmatrix} 3 & 1 \\ 5 & -2 \end{bmatrix}$`], key: 'a', sol: r`$A + A^T = \begin{bmatrix} 6 & 6 \\ 6 & -4 \end{bmatrix}$; halving gives option (a). Option (b) is the skew-symmetric part, (c) forgets the half and (d) is just $A^T$.`, d: 3, c: 'application', t: [3], time: 75 }), (C) => { C.which([[3, 3, 3, -2], [0, 2, -2, 0], [6, 6, 6, -4], [3, 1, 5, -2]], flat(scal(0.5, add(A15, T(A15))))); C.assert(eqM(scal(0.5, sub(A15, T(A15))), [[0, 2], [-2, 0]]), 'option (b) is the skew part'); });
Q('m16', mk.mcq({ stem: r`A square matrix $A$ has inverse $B$. Which statement must hold?`, opts: ['$AB = BA = I$', '$AB = I$, but $BA$ may differ', '$A + B = I$', '$AB = O$'], key: 'a', sol: r`By definition, $B$ is the inverse of the square matrix $A$ when $AB = BA = I$, with $I$ the identity matrix of the same order.`, d: 1, c: 'recall', t: [4], time: 30 }), (C) => { const A = [[2, 1], [1, 1]], B = [[1, -1], [-1, 2]]; C.assert(isInverse(A, B), 'example inverse pair'); C.key('a'); });
const A17 = [[2, 1], [1, 1]];
Q('m17', mk.mcq({ stem: r`The inverse of $${bm(A17)}$ is`, opts: [r`$\begin{bmatrix} 1 & -1 \\ -1 & 2 \end{bmatrix}$`, r`$\begin{bmatrix} 1 & 1 \\ 1 & 2 \end{bmatrix}$`, r`$\begin{bmatrix} 2 & -1 \\ -1 & 1 \end{bmatrix}$`, r`$\begin{bmatrix} \frac12 & 1 \\ 1 & 1 \end{bmatrix}$`], key: 'a', sol: r`Multiply to check: $\begin{bmatrix} 2 & 1 \\ 1 & 1 \end{bmatrix}\begin{bmatrix} 1 & -1 \\ -1 & 2 \end{bmatrix} = \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix}$, and the product in the other order is also $I$. Taking reciprocals of the entries, as in (d), never gives an inverse.`, d: 2, c: 'understanding', t: [4], time: 60 }), (C) => C.which([[[1, -1], [-1, 2]], [[1, 1], [1, 2]], [[2, -1], [-1, 1]], [[0.5, 1], [1, 1]]].map((B) => isInverse(A17, B)), true));
const A18 = [[2, 1], [3, 2]];
Q('m18', mk.mcq({ stem: r`A square matrix $A$ satisfies $A^2 - 4A + I = O$. Then $A^{-1}$ equals`, opts: ['$4I - A$', '$A - 4I$', '$4A - I$', '$A + 4I$'], key: 'a', sol: r`Rewrite as $I = 4A - A^2 = A(4I - A)$. Similarly $(4I - A)A = I$. So $A^{-1} = 4I - A$. (For instance $A = \begin{bmatrix} 2 & 1 \\ 3 & 2 \end{bmatrix}$ satisfies the relation and its inverse is $\begin{bmatrix} 2 & -1 \\ -3 & 2 \end{bmatrix}$.)`, d: 3, c: 'application', t: [4], time: 75 }), (C) => {
  const A = A18; C.assert(eqM(add(sub(mul(A, A), scal(4, A)), I(2)), O(2)), 'relation holds');
  C.which([sub(scal(4, I(2)), A), sub(A, scal(4, I(2))), sub(scal(4, A), I(2)), add(A, scal(4, I(2)))].map((B) => isInverse(A, B)), true);
  C.assert(eqM(sub(scal(4, I(2)), A), [[2, -1], [-3, 2]]), 'example inverse in solution');
});
Q('m19', mk.mcq({ stem: r`$A$ is a $3 \times 2$ matrix. Both $AB$ and $BA$ are defined. The order of $B$ is`, opts: [r`$2 \times 3$`, r`$3 \times 2$`, r`$2 \times 2$`, r`$3 \times 3$`], key: 'a', sol: r`$AB$ defined: $B$ has $2$ rows (the columns of $A$). $BA$ defined: $B$ has $3$ columns (the rows of $A$). So $B$ is $2 \times 3$.`, d: 3, c: 'analysis', t: [2], time: 60 }), (C) => {
  const ok = ([p, q]) => { try { mul(O(3, 2), O(p, q)); mul(O(p, q), O(3, 2)); return true; } catch { return false; } };
  C.which([[2, 3], [3, 2], [2, 2], [3, 3]].map(ok), true);
});

// =============================================================== assertion-reason (keys a b c d a b)
Q('ar1', mk.ar({ a: r`If $A$ and $B$ are both $2 \times 3$ matrices, the product $AB$ is not defined.`, r: r`The product $AB$ is defined only when the number of columns of $A$ equals the number of rows of $B$.`, key: 'a', sol: r`$A$ has $3$ columns and $B$ has $2$ rows, and $3 \ne 2$. By R, $AB$ is not defined, so R explains A.`, d: 2, c: 'understanding', t: [2] }), (C) => { let defined = true; try { mul(O(2, 3), O(2, 3)); } catch { defined = false; } C.assert(!defined, 'AB undefined'); C.key('a'); });
Q('ar2', mk.ar({ a: r`$\begin{bmatrix} 0 & 4 \\ -4 & 0 \end{bmatrix}$ is a skew-symmetric matrix.`, r: 'Every diagonal element of a skew-symmetric matrix is zero.', key: 'b', sol: r`A is true: $A^T = \begin{bmatrix} 0 & -4 \\ 4 & 0 \end{bmatrix} = -A$. R is also true. But a zero diagonal alone does not make a matrix skew-symmetric (for example $\begin{bmatrix} 0 & 1 \\ 1 & 0 \end{bmatrix}$), so R does not explain A.`, d: 3, c: 'analysis', t: [3] }), (C) => { C.assert(isSkew([[0, 4], [-4, 0]]) && !isSkew([[0, 1], [1, 0]]), 'skew; zero diagonal not sufficient'); C.key('b'); });
Q('ar3', mk.ar({ a: 'The product of two non-zero matrices can be the zero matrix.', r: r`If $AB = O$ for matrices $A$ and $B$, then $A = O$ or $B = O$.`, key: 'c', sol: r`A is true: $\begin{bmatrix} 1 & 1 \\ 2 & 2 \end{bmatrix}\begin{bmatrix} 1 & -1 \\ -1 & 1 \end{bmatrix} = \begin{bmatrix} 0 & 0 \\ 0 & 0 \end{bmatrix}$. That same example shows R is false: the zero-product rule of real numbers does not carry over to matrices.`, d: 3, c: 'analysis', t: [2] }), (C) => { C.assert(eqM(mul([[1, 1], [2, 2]], [[1, -1], [-1, 1]]), O(2)), 'zero product'); C.key('c'); });
Q('ar4', mk.ar({ a: 'Every square matrix has an inverse.', r: 'The inverse of a square matrix, when it exists, is unique.', key: 'd', sol: r`A is false: the zero matrix $O$ of order $2$ has no inverse, since $OB = O \ne I$ for every $B$. R is true (if $B$ and $C$ are both inverses, $B = BI = B(AC) = (BA)C = IC = C$).`, d: 2, c: 'understanding', t: [4] }), (C) => { C.assert(eqM(mul(O(2), [[1, 2], [3, 4]]), O(2)), 'OB = O'); C.key('d'); });
Q('ar5', mk.ar({ a: r`For every square matrix $A$, the matrix $A + A^T$ is symmetric.`, r: r`$(A + A^T)^T = A^T + (A^T)^T = A^T + A$.`, key: 'a', sol: r`R computes the transpose of $A + A^T$ and finds it equal to $A + A^T$ (addition is commutative). That is exactly what symmetric means, so A is true and R explains it.`, d: 2, c: 'understanding', t: [3] }), (C) => { const A = [[1, 7, -2], [0, 3, 5], [4, -1, 6]]; C.assert(isSym(add(A, T(A))), 'A + A^T symmetric'); C.key('a'); });
Q('ar6', mk.ar({ a: r`If $A = \begin{bmatrix} 2 & 0 \\ 0 & 2 \end{bmatrix}$, then $A^2 = 4I$.`, r: 'The transpose of a diagonal matrix is the matrix itself.', key: 'b', sol: r`A: $A = 2I$, so $A^2 = 4I^2 = 4I$, true. R is true too, since a diagonal matrix has zeros off the diagonal. But A follows from $A = 2I$ and $I^2 = I$; transposes play no part, so R does not explain A.`, d: 2, c: 'understanding', t: [2, 3] }), (C) => { const A = [[2, 0], [0, 2]]; C.assert(eqM(mul(A, A), scal(4, I(2))) && eqM(T(A), A), 'A^2 = 4I; diagonal is symmetric'); C.key('b'); });

// =============================================================== true / false
Q('tf1', mk.tf({ stem: 'True or false: every scalar matrix is a diagonal matrix.', key: 't', sol: r`True. A scalar matrix is a diagonal matrix whose diagonal elements are all equal, such as $5I$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert(eqM(scal(5, I(3)).map((row, i) => row.map((v, j) => (i === j ? 0 : v))), O(3)), 'off-diagonal zero'); C.key('t'); });
Q('tf2', mk.tf({ stem: r`True or false: for all square matrices $A$ and $B$ of the same order, $(A + B)(A - B) = A^2 - B^2$.`, key: 'f', sol: r`False. Expanding gives $A^2 - AB + BA - B^2$, which equals $A^2 - B^2$ only when $AB = BA$. With $A = \begin{bmatrix} 1 & 1 \\ 0 & 0 \end{bmatrix}$ and $B = \begin{bmatrix} 0 & 0 \\ 1 & 0 \end{bmatrix}$ the two sides differ.`, d: 3, c: 'analysis', t: [2] }), (C) => { const A = [[1, 1], [0, 0]], B = [[0, 0], [1, 0]]; C.assert(!eqM(mul(add(A, B), sub(A, B)), sub(mul(A, A), mul(B, B))), 'counterexample'); C.key('f'); });
Q('tf3', mk.tf({ stem: r`True or false: the transpose of a $2 \times 5$ matrix is also of order $2 \times 5$.`, key: 'f', sol: r`False. Rows become columns, so the transpose has order $5 \times 2$.`, d: 1, c: 'recall', t: [3] }), (C) => { const P = T(O(2, 5)); C.assert(P.length === 5 && P[0].length === 2, '5x2'); C.key('f'); });
Q('tf4', mk.tf({ stem: 'True or false: a square matrix that is both symmetric and skew-symmetric must be the zero matrix.', key: 't', sol: r`True. $A^T = A$ and $A^T = -A$ give $A = -A$, so $2A = O$ and $A = O$.`, d: 2, c: 'understanding', t: [3] }), (C) => { C.assert(isSym(O(3)) && isSkew(O(3)) && !isSkew([[1, 0], [0, 1]]), 'O is both; I is not skew'); C.key('t'); });
Q('tf5', mk.tf({ stem: 'True or false: a matrix of order 2 × 3 can have an inverse.', key: 'f', sol: r`False. Only square matrices can be invertible: $AB = BA = I$ needs $AB$ and $BA$ to be identity matrices of the same order, which forces $A$ to be square.`, d: 2, c: 'understanding', t: [4] }), (C) => { const AB = mul(O(2, 3), O(3, 2)), BA = mul(O(3, 2), O(2, 3)); C.assert(AB.length !== BA.length, 'AB is 2x2, BA is 3x3'); C.key('f'); });

// =============================================================== fill in the blank
Q('fi1', mk.fill({ stem: r`The number of elements in a matrix of order $4 \times 3$ is ____.`, acc: [['12']], sol: r`$4 \times 3 = 12$ elements.`, d: 1, c: 'recall', t: [1] }), (C) => C.blank(O(4, 3).flat().length));
const A_fi2 = [[1, 3], [2, -1]];
Q('fi2', mk.fill({ stem: r`If $A = ${bm(A_fi2)}$ and $A^2 = kI$, then $k = $ ____.`, acc: [['7']], sol: r`$A^2 = \begin{bmatrix} 1 + 6 & 3 - 3 \\ 2 - 2 & 6 + 1 \end{bmatrix} = \begin{bmatrix} 7 & 0 \\ 0 & 7 \end{bmatrix} = 7I$.`, d: 3, c: 'application', t: [2] }), (C) => { const A2 = mul(A_fi2, A_fi2); C.assert(eqM(A2, scal(A2[0][0], I(2))), 'A^2 scalar'); C.blank(A2[0][0]); });
Q('fi3', mk.fill({ stem: r`If $\begin{bmatrix} 2 & x \\ 5 & 1 \end{bmatrix}$ is symmetric, then $x = $ ____.`, acc: [['5']], sol: r`Symmetric needs $a_{12} = a_{21}$, so $x = 5$.`, d: 1, c: 'understanding', t: [3] }), (C) => C.blank([1, 2, 3, 4, 5, 6, 7].find((x) => isSym([[2, x], [5, 1]]))));
Q('fi4', mk.fill({ stem: r`In a skew-symmetric matrix $A = [a_{ij}]$ of order $3$, $a_{12} = 4$. Then $a_{21} = $ ____.`, acc: [['-4', '−4']], sol: r`Skew-symmetric: $a_{21} = -a_{12} = -4$.`, d: 2, c: 'understanding', t: [3] }), (C) => C.blank(-4));
const A_fi5 = [[1, 2], [0, 1]];
Q('fi5', mk.fill({ stem: r`If $A = ${bm(A_fi5)}$ and $B = \begin{bmatrix} 1 & q \\ 0 & 1 \end{bmatrix}$ is the inverse of $A$, then $q = $ ____.`, acc: [['-2', '−2']], sol: r`$AB = \begin{bmatrix} 1 & q + 2 \\ 0 & 1 \end{bmatrix} = I$ needs $q + 2 = 0$, so $q = -2$.`, d: 2, c: 'application', t: [4] }), (C) => C.blank([-3, -2, -1, 0, 1, 2, 3].find((q) => isInverse(A_fi5, [[1, q], [0, 1]]))));

// =============================================================== numerical
Q('n1', mk.num({ stem: r`A $3 \times 3$ matrix $A = [a_{ij}]$ has $a_{ij} = i^2 - j$. Find the sum of all nine elements of $A$.`, value: 24, sol: r`Rows: $i = 1$ gives $0, -1, -2$; $i = 2$ gives $3, 2, 1$; $i = 3$ gives $8, 7, 6$. Sum $= -3 + 6 + 21 = 24$.`, scheme: [['Sum = 24', 1]], d: 3, c: 'application', t: [1], time: 120 }), (C) => { const A = fromRule(3, 3, (i, j) => i * i - j); C.val(sum(A)); C.sol([21, 6, 3]); });
const A_n2 = [[2, -1], [3, 4]], B_n2 = [[1, 5], [-2, 0]];
Q('n2', mk.num({ stem: r`$A = ${bm(A_n2)}$ and $B = ${bm(B_n2)}$. Find the sum of all the elements of $2A - B$.`, value: 12, sol: r`$2A - B = \begin{bmatrix} 3 & -7 \\ 8 & 8 \end{bmatrix}$; $3 - 7 + 8 + 8 = 12$.`, scheme: [['12', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { const M = sub(scal(2, A_n2), B_n2); C.assert(eqM(M, [[3, -7], [8, 8]]), 'matrix'); C.val(sum(M)); });
const A_n3 = [[1, 2, 0], [3, -1, 4]], B_n3 = [[2, 1], [0, 3], [5, -2]];
Q('n3', mk.num({ stem: r`$A = ${bm(A_n3)}$ and $B = ${bm(B_n3)}$. Find the element in row 2, column 1 of $AB$.`, value: 26, sol: r`Row 2 of $A$ times column 1 of $B$: $3(2) + (-1)(0) + 4(5) = 6 + 0 + 20 = 26$.`, scheme: [['26', 1]], d: 2, c: 'understanding', t: [2], time: 75 }), (C) => C.val(mul(A_n3, B_n3)[1][0]));
const qty_n4 = [[40, 25, 30]], price_n4 = [[12], [8], [15]];
Q('n4', mk.num({ stem: r`A school canteen in Nagpur sells $40$ vada pav, $25$ cups of tea and $30$ sandwiches in a morning. Their prices are ₹$12$, ₹$8$ and ₹$15$. Writing the sales as a row matrix and the prices as a column matrix, find the morning's takings (in ₹) as their product.`, value: 1130, unit: '₹', sol: r`$\begin{bmatrix} 40 & 25 & 30 \end{bmatrix}\begin{bmatrix} 12 \\ 8 \\ 15 \end{bmatrix} = 480 + 200 + 450 = 1130$.`, scheme: [['1130', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => C.val(mul(qty_n4, price_n4)[0][0]));
const A_n5 = [[1, 4], [-2, 3]];
Q('n5', mk.num({ stem: r`For $A = ${bm(A_n5)}$, find the element in row 1, column 2 of the skew-symmetric matrix $\dfrac12(A - A^T)$.`, value: 3, sol: r`$A - A^T = \begin{bmatrix} 0 & 6 \\ -6 & 0 \end{bmatrix}$; half of it has $3$ in row 1, column 2.`, scheme: [['3', 1]], d: 2, c: 'understanding', t: [3], time: 75 }), (C) => { const K = scal(0.5, sub(A_n5, T(A_n5))); C.assert(isSkew(K), 'skew'); C.val(K[0][1]); });
const A_n6 = [[3, 2], [4, 3]];
Q('n6', mk.num({ stem: r`$A = ${bm(A_n6)}$ has inverse $\begin{bmatrix} p & -2 \\ -4 & q \end{bmatrix}$. Find $p + q$.`, value: 6, sol: r`$AA^{-1} = I$: row 1 times column 1 gives $3p - 8 = 1$, so $p = 3$; row 2 times column 2 gives $-8 + 3q = 1$, so $q = 3$. Hence $p + q = 6$.`, scheme: [['6', 1]], d: 3, c: 'application', t: [4], time: 120 }), (C) => { const B = [[3, -2], [-4, 3]]; C.assert(isInverse(A_n6, B), 'p = q = 3 gives the inverse'); C.val(B[0][0] + B[1][1]); });
const A_n7 = [[1, 1], [0, 1]];
Q('n7', mk.num({ stem: r`For $A = ${bm(A_n7)}$, find the element in row 1, column 2 of $A^{10}$.`, value: 10, sol: r`$A^2 = \begin{bmatrix} 1 & 2 \\ 0 & 1 \end{bmatrix}$, $A^3 = \begin{bmatrix} 1 & 3 \\ 0 & 1 \end{bmatrix}$: each multiplication by $A$ adds $1$ to that entry, so $A^n = \begin{bmatrix} 1 & n \\ 0 & 1 \end{bmatrix}$ and the entry of $A^{10}$ is $10$.`, scheme: [['10', 1]], d: 3, c: 'analysis', t: [2], time: 120 }), (C) => { C.val(pow(A_n7, 10)[0][1]); C.assert(eqM(pow(A_n7, 3), [[1, 3], [0, 1]]), 'A^3'); });

// =============================================================== short answer, 2 marks
const R201 = fromRule(2, 3, (i, j) => i * i + j - 2);
Q('s201', mk.short({ marks: 2, stem: r`Construct the $2 \times 3$ matrix $A = [a_{ij}]$ with $a_{ij} = i^2 + j - 2$.`, model: r`Row 1 ($i = 1$): $1 + j - 2 = j - 1$, giving $0, 1, 2$. Row 2 ($i = 2$): $4 + j - 2 = j + 2$, giving $3, 4, 5$. So $A = \begin{bmatrix} 0 & 1 & 2 \\ 3 & 4 & 5 \end{bmatrix}$.`, sol: 'Substitute each pair (i, j) in turn.', scheme: [['Row 1 correct', 1], ['Row 2 correct', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => C.model([bm(R201)]));
Q('s202', mk.short({ marks: 2, stem: r`Find $x$, $y$ and $z$ if $\begin{bmatrix} 2x + y & 3 \\ x - y & z + 1 \end{bmatrix} = \begin{bmatrix} 7 & 3 \\ 2 & 0 \end{bmatrix}$.`, model: r`Equating corresponding elements: $2x + y = 7$, $x - y = 2$ and $z + 1 = 0$. Adding the first two, $3x = 9$, so $x = 3$ and $y = 1$. Also $z = -1$.`, sol: 'Equal matrices: equate corresponding entries.', scheme: [['Equations from equality', 1], ['x = 3, y = 1, z = −1', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => { const [x, y, z] = [3, 1, -1]; C.assert(2 * x + y === 7 && x - y === 2 && z + 1 === 0, 'satisfies all three'); C.model([3, 1, 'z = -1']); });
const A203 = [[3, -1], [2, 5]], B203 = [[1, 7], [-4, 3]];
Q('s203', mk.short({ marks: 2, stem: r`$A = ${bm(A203)}$ and $B = ${bm(B203)}$. Find the matrix $X$ such that $2X - A = B$.`, model: r`$2X = A + B = \begin{bmatrix} 4 & 6 \\ -2 & 8 \end{bmatrix}$, so $X = \dfrac12(A + B) = \begin{bmatrix} 2 & 3 \\ -1 & 4 \end{bmatrix}$.`, sol: 'Treat it like a linear equation: add A, then multiply by one half.', scheme: [['2X = A + B computed', 1], ['X', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { const X = scal(0.5, add(A203, B203)); C.assert(eqM(sub(scal(2, X), A203), B203), 'X satisfies'); C.model([bm(X), bm(add(A203, B203))]); });
const A204 = [[1, 2], [0, 3]], B204 = [[2, 0], [1, 1]];
Q('s204', mk.short({ marks: 2, stem: r`Show that $AB \ne BA$ for $A = ${bm(A204)}$ and $B = ${bm(B204)}$.`, model: r`$AB = \begin{bmatrix} 4 & 2 \\ 3 & 3 \end{bmatrix}$ and $BA = \begin{bmatrix} 2 & 4 \\ 1 & 5 \end{bmatrix}$. Already the first entries differ ($4 \ne 2$), so $AB \ne BA$: matrix multiplication is not commutative.`, sol: 'Compute both products and compare.', scheme: [['AB', 1], ['BA and conclusion', 1]], d: 2, c: 'application', t: [2], time: 120 }), (C) => { C.model([bm(mul(A204, B204)), bm(mul(B204, A204))]); C.assert(!eqM(mul(A204, B204), mul(B204, A204)), 'differ'); });
const A205 = [[1, 2], [2, 1]];
Q('s205', mk.short({ marks: 2, stem: r`For $A = ${bm(A205)}$, find the number $k$ such that $A^2 - 2A = kI$.`, model: r`$A^2 = \begin{bmatrix} 5 & 4 \\ 4 & 5 \end{bmatrix}$ and $2A = \begin{bmatrix} 2 & 4 \\ 4 & 2 \end{bmatrix}$, so $A^2 - 2A = \begin{bmatrix} 3 & 0 \\ 0 & 3 \end{bmatrix} = 3I$. Hence $k = 3$.`, sol: 'Square A first, then subtract.', scheme: [['A squared', 1], ['k = 3', 1]], d: 3, c: 'application', t: [2], time: 120 }), (C) => { const M = sub(mul(A205, A205), scal(2, A205)); C.assert(eqM(M, scal(3, I(2))), '3I'); C.model([bm(mul(A205, A205)), 'k = 3']); });
const A206 = [[2, -1], [3, 0]], B206 = [[1, 4], [-2, 5]];
Q('s206', mk.short({ marks: 2, stem: r`For $A = ${bm(A206)}$ and $B = ${bm(B206)}$, verify that $(A + B)^T = A^T + B^T$.`, model: r`$A + B = \begin{bmatrix} 3 & 3 \\ 1 & 5 \end{bmatrix}$, so $(A + B)^T = \begin{bmatrix} 3 & 1 \\ 3 & 5 \end{bmatrix}$. Also $A^T = \begin{bmatrix} 2 & 3 \\ -1 & 0 \end{bmatrix}$ and $B^T = \begin{bmatrix} 1 & -2 \\ 4 & 5 \end{bmatrix}$, whose sum is $\begin{bmatrix} 3 & 1 \\ 3 & 5 \end{bmatrix}$. The two sides are equal.`, sol: 'Work out each side separately.', scheme: [['Left side', 1], ['Right side and equality', 1]], d: 2, c: 'understanding', t: [3], time: 120 }), (C) => { const L = T(add(A206, B206)), R = add(T(A206), T(B206)); C.assert(eqM(L, R), 'equal'); C.model([bm(L), bm(T(A206)), bm(T(B206)), bm(add(A206, B206))]); });
Q('s207', mk.short({ marks: 2, stem: r`Prove that for any square matrix $A$, the matrix $A - A^T$ is skew-symmetric.`, model: r`$(A - A^T)^T = A^T - (A^T)^T = A^T - A = -(A - A^T)$. A matrix whose transpose is its negative is skew-symmetric, so $A - A^T$ is skew-symmetric.`, sol: 'Use the transpose of a difference and the fact that the transpose of the transpose is the matrix itself.', scheme: [['Transpose taken correctly', 1], ['Equals −(A − Aᵀ), conclusion', 1]], d: 3, c: 'analysis', t: [3], time: 90 }), (C) => { for (const A of [[[1, 2], [3, 4]], [[5, -1, 0], [2, 2, 7], [-3, 4, 1]]]) C.assert(isSkew(sub(A, T(A))), 'A - A^T skew for sample'); C.model(['-(A - A^T)']); });
const A208 = [[5, 2], [2, 1]], B208 = [[1, -2], [-2, 5]];
Q('s208', mk.short({ marks: 2, stem: r`Show that $B = ${bm(B208)}$ is the inverse of $A = ${bm(A208)}$.`, model: r`$AB = \begin{bmatrix} 5 - 4 & -10 + 10 \\ 2 - 2 & -4 + 5 \end{bmatrix} = \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix}$ and $BA = \begin{bmatrix} 5 - 4 & 2 - 2 \\ -10 + 10 & -4 + 5 \end{bmatrix} = \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix}$. Since $AB = BA = I$, $B = A^{-1}$.`, sol: 'Both products must be checked.', scheme: [['AB = I', 1], ['BA = I and conclusion', 1]], d: 2, c: 'understanding', t: [4], time: 120 }), (C) => { C.assert(isInverse(A208, B208), 'inverse'); C.model([bm(I(2))]); });
const A209 = [[2, 3], [1, 2]];
Q('s209', mk.short({ marks: 2, stem: r`For $A = ${bm(A209)}$, show that $A^2 - 4A + I = O$ and hence write $A^{-1}$.`, model: r`$A^2 = \begin{bmatrix} 7 & 12 \\ 4 & 7 \end{bmatrix}$ and $4A = \begin{bmatrix} 8 & 12 \\ 4 & 8 \end{bmatrix}$, so $A^2 - 4A + I = \begin{bmatrix} 0 & 0 \\ 0 & 0 \end{bmatrix} = O$. Then $A(4I - A) = I$, so $A^{-1} = 4I - A = \begin{bmatrix} 2 & -3 \\ -1 & 2 \end{bmatrix}$.`, sol: 'Rearrange the relation as A times something equals I.', scheme: [['Relation verified', 1], ['Inverse', 1]], d: 3, c: 'application', t: [4], time: 150 }), (C) => { C.assert(eqM(add(sub(mul(A209, A209), scal(4, A209)), I(2)), O(2)), 'relation'); const B = sub(scal(4, I(2)), A209); C.assert(isInverse(A209, B), 'inverse'); C.model([bm(mul(A209, A209)), bm(B)]); });

// =============================================================== short answer, 3 marks
const stock301 = [[25, 40, 15], [30, 20, 35]];
Q('s301', mk.short({ marks: 3, stem: r`A sports shop in Jalandhar has two branches. Branch P stocks $25$ bats, $40$ balls and $15$ helmets; branch Q stocks $30$ bats, $20$ balls and $35$ helmets.
(a) Write the stock as a matrix $S$ with branches as rows and items as columns, and state its order.
(b) What does $s_{23}$ represent? Give its value.
(c) Each branch doubles the stock of every item. Find the new stock matrix $2S$ (which equals $S + S$).`, model: r`(a) $S = \begin{bmatrix} 25 & 40 & 15 \\ 30 & 20 & 35 \end{bmatrix}$, order $2 \times 3$.
(b) $s_{23}$ is row 2 (branch Q), column 3 (helmets): branch Q has $35$ helmets.
(c) $2S = \begin{bmatrix} 50 & 80 & 30 \\ 60 & 40 & 70 \end{bmatrix}$.`, sol: 'Rows for branches, columns for items; scalar multiplication doubles every entry.', scheme: [['Matrix and order', 1], ['Meaning and value of s₂₃', 1], ['2S', 1]], d: 2, c: 'application', t: [1, 2], time: 180 }), (C) => { C.model([bm(stock301), stock301[1][2], bm(scal(2, stock301))]); C.assert(eqM(add(stock301, stock301), scal(2, stock301)), 'S + S = 2S'); });
const A302 = (x) => [[2, 1], [3, x]];
Q('s302', mk.short({ marks: 3, stem: r`Find $x$ and $y$ if $\begin{bmatrix} 2 & 1 \\ 3 & x \end{bmatrix}\begin{bmatrix} 1 \\ y \end{bmatrix} = \begin{bmatrix} 5 \\ 9 \end{bmatrix}$.`, model: r`The product is $\begin{bmatrix} 2 + y \\ 3 + xy \end{bmatrix}$. Equating: $2 + y = 5$, so $y = 3$. Then $3 + 3x = 9$, so $x = 2$.`, sol: 'Multiply first, then equate entries; the first equation gives y.', scheme: [['Product written', 1], ['y = 3', 1], ['x = 2', 1]], d: 3, c: 'application', t: [1, 2], time: 150 }), (C) => { C.assert(eqM(mul(A302(2), [[1], [3]]), [[5], [9]]), 'x = 2, y = 3 satisfy'); C.model(['y = 3', 'x = 2']); });
const A303 = [[2, 1], [1, 3]];
Q('s303', mk.short({ marks: 3, stem: r`If $f(x) = x^2 - 5x + 4$ and $A = ${bm(A303)}$, find $f(A) = A^2 - 5A + 4I$.`, model: r`$A^2 = \begin{bmatrix} 5 & 5 \\ 5 & 10 \end{bmatrix}$, $5A = \begin{bmatrix} 10 & 5 \\ 5 & 15 \end{bmatrix}$ and $4I = \begin{bmatrix} 4 & 0 \\ 0 & 4 \end{bmatrix}$. So $f(A) = \begin{bmatrix} 5 - 10 + 4 & 5 - 5 + 0 \\ 5 - 5 + 0 & 10 - 15 + 4 \end{bmatrix} = \begin{bmatrix} -1 & 0 \\ 0 & -1 \end{bmatrix} = -I$.`, sol: 'The constant term becomes a multiple of the identity matrix.', scheme: [['A squared', 1], ['5A and 4I', 1], ['f(A) = −I', 1]], d: 3, c: 'application', t: [2], time: 180 }), (C) => { const F = add(sub(mul(A303, A303), scal(5, A303)), scal(4, I(2))); C.model([bm(mul(A303, A303)), bm(scal(5, A303)), bm(F)]); C.assert(eqM(F, scal(-1, I(2))), '-I'); });
const A304 = [[4, 7], [-1, 2]];
Q('s304', mk.short({ marks: 3, stem: r`Express $A = ${bm(A304)}$ as the sum of a symmetric matrix and a skew-symmetric matrix.`, model: r`$A^T = \begin{bmatrix} 4 & -1 \\ 7 & 2 \end{bmatrix}$. $P = \dfrac12(A + A^T) = \begin{bmatrix} 4 & 3 \\ 3 & 2 \end{bmatrix}$, which is symmetric. $Q = \dfrac12(A - A^T) = \begin{bmatrix} 0 & 4 \\ -4 & 0 \end{bmatrix}$, which is skew-symmetric. Check: $P + Q = \begin{bmatrix} 4 & 7 \\ -1 & 2 \end{bmatrix} = A$.`, sol: 'Use P = ½(A + Aᵀ) and Q = ½(A − Aᵀ).', scheme: [['Transpose and P', 1], ['Q', 1], ['P + Q = A checked', 1]], d: 3, c: 'application', t: [3], time: 180 }), (C) => { const P = scal(0.5, add(A304, T(A304))), K = scal(0.5, sub(A304, T(A304))); C.assert(isSym(P) && isSkew(K) && eqM(add(P, K), A304), 'decomposition'); C.model([bm(T(A304)), bm(P), bm(K)]); });
const A305 = [[1, 0, 2], [-1, 3, 1]], B305 = [[2, 1], [0, -1], [1, 4]];
Q('s305', mk.short({ marks: 3, stem: r`For $A = ${bm(A305)}$ and $B = ${bm(B305)}$, verify that $(AB)^T = B^TA^T$.`, model: r`$AB = \begin{bmatrix} 4 & 9 \\ -1 & 0 \end{bmatrix}$, so $(AB)^T = \begin{bmatrix} 4 & -1 \\ 9 & 0 \end{bmatrix}$. $B^T = \begin{bmatrix} 2 & 0 & 1 \\ 1 & -1 & 4 \end{bmatrix}$ and $A^T = \begin{bmatrix} 1 & -1 \\ 0 & 3 \\ 2 & 1 \end{bmatrix}$, and $B^TA^T = \begin{bmatrix} 4 & -1 \\ 9 & 0 \end{bmatrix}$. The two sides agree.`, sol: 'Compute AB first, then the transposes; note the reversed order.', scheme: [['AB', 1], ['Transposes of A and B', 1], ['Product and equality', 1]], d: 3, c: 'understanding', t: [2, 3], time: 210 }), (C) => { const L = T(mul(A305, B305)), R = mul(T(B305), T(A305)); C.assert(eqM(L, R), 'equal'); C.model([bm(mul(A305, B305)), bm(L), bm(T(B305)), bm(T(A305))]); });
const A306 = [[3, 5], [1, 2]];
Q('s306', mk.short({ marks: 3, stem: r`Let $A = ${bm(A306)}$. Find $A^{-1}$ by writing $A^{-1} = \begin{bmatrix} p & q \\ r & s \end{bmatrix}$ and using $AA^{-1} = I$. Verify that $A^{-1}A = I$ as well.`, model: r`$AA^{-1} = \begin{bmatrix} 3p + 5r & 3q + 5s \\ p + 2r & q + 2s \end{bmatrix} = \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix}$.
Column 1: $p + 2r = 0$ gives $p = -2r$; then $-6r + 5r = 1$, so $r = -1$, $p = 2$.
Column 2: $q + 2s = 1$ gives $q = 1 - 2s$; then $3 - 6s + 5s = 0$, so $s = 3$, $q = -5$.
$A^{-1} = \begin{bmatrix} 2 & -5 \\ -1 & 3 \end{bmatrix}$, and $A^{-1}A = \begin{bmatrix} 6 - 5 & 10 - 10 \\ -3 + 3 & -5 + 6 \end{bmatrix} = I$.`, sol: 'Two pairs of linear equations, one for each column.', scheme: [['Equations from AA⁻¹ = I', 1], ['p, q, r, s found', 1], ['A⁻¹A = I verified', 1]], d: 3, c: 'application', t: [4], time: 240 }), (C) => { const B = [[2, -5], [-1, 3]]; C.assert(isInverse(A306, B), 'inverse'); C.model([bm(B), 'r = -1', 's = 3', 'q = -5', 'p = 2']); });
Q('s307', mk.short({ marks: 3, stem: 'Prove that a square matrix cannot have two different inverses.', model: r`Suppose $B$ and $C$ are both inverses of the square matrix $A$, so $AB = BA = I$ and $AC = CA = I$.
Then $B = BI = B(AC)$.
By associativity, $B(AC) = (BA)C = IC = C$.
So $B = C$: the inverse, when it exists, is unique.`, sol: 'Start from B = BI and replace I by AC; associativity of multiplication does the rest.', scheme: [['Assume two inverses B and C', 1], ['B = B(AC) = (BA)C', 1], ['= IC = C, conclusion', 1]], d: 4, c: 'analysis', t: [4], time: 180 }), (C) => { const A = [[2, 1], [1, 1]], B = [[1, -1], [-1, 2]]; C.assert(eqM(mul(B, mul(A, B)), mul(mul(B, A), B)), 'associativity on a sample'); C.model(['B = C', '(BA)C']); });
const A308 = [[1, 2], [-1, -2]];
Q('s308', mk.short({ marks: 3, stem: r`For $A = ${bm(A308)}$, show that $A^2 = -A$. Hence find $A^3$ without multiplying three matrices, and explain why $A(A + I) = O$ even though neither $A$ nor $A + I$ is the zero matrix.`, model: r`$A^2 = \begin{bmatrix} 1 - 2 & 2 - 4 \\ -1 + 2 & -2 + 4 \end{bmatrix} = \begin{bmatrix} -1 & -2 \\ 1 & 2 \end{bmatrix} = -A$.
$A^3 = A \cdot A^2 = A(-A) = -A^2 = A$.
$A(A + I) = A^2 + A = -A + A = O$, while $A + I = \begin{bmatrix} 2 & 2 \\ -1 & -1 \end{bmatrix} \ne O$. Matrices can have a zero product with both factors non-zero.`, sol: 'Use the relation A² = −A repeatedly.', scheme: [['A² = −A shown', 1], ['A³ = A', 1], ['A(A + I) = O with reason', 1]], d: 4, c: 'analysis', t: [2], time: 210 }), (C) => { C.assert(eqM(mul(A308, A308), scal(-1, A308)) && eqM(pow(A308, 3), A308) && eqM(mul(A308, add(A308, I(2))), O(2)), 'relations'); C.model([bm(mul(A308, A308)), bm(add(A308, I(2)))]); });

// =============================================================== long answer, 5 marks
const A_l1 = [[1, 2, -1], [0, 1, 3], [2, -1, 0]], B_l1 = [[2, 0, 1], [1, -1, 0], [0, 3, 2]];
Q('l01', mk.long({ stem: r`Let $A = ${bm(A_l1)}$ and $B = ${bm(B_l1)}$. Find $AB$ and $BA$, show that $AB \ne BA$, and find $AB - BA$.`, model: r`**$AB$** (row of $A$ times column of $B$):
Row 1: $(2 + 2 + 0,\ 0 - 2 - 3,\ 1 + 0 - 2) = (4, -5, -1)$; row 2: $(0 + 1 + 0,\ 0 - 1 + 9,\ 0 + 0 + 6) = (1, 8, 6)$; row 3: $(4 - 1 + 0,\ 0 + 1 + 0,\ 2 + 0 + 0) = (3, 1, 2)$.
$AB = \begin{bmatrix} 4 & -5 & -1 \\ 1 & 8 & 6 \\ 3 & 1 & 2 \end{bmatrix}$.
**$BA$:** row 1: $(2 + 0 + 2,\ 4 + 0 - 1,\ -2 + 0 + 0) = (4, 3, -2)$; row 2: $(1 + 0 + 0,\ 2 - 1 + 0,\ -1 - 3 + 0) = (1, 1, -4)$; row 3: $(0 + 0 + 4,\ 0 + 3 - 2,\ 0 + 9 + 0) = (4, 1, 9)$.
$BA = \begin{bmatrix} 4 & 3 & -2 \\ 1 & 1 & -4 \\ 4 & 1 & 9 \end{bmatrix}$.
The entries in row 1, column 2 differ ($-5 \ne 3$), so $AB \ne BA$.
$AB - BA = \begin{bmatrix} 0 & -8 & 1 \\ 0 & 7 & 10 \\ -1 & 0 & -7 \end{bmatrix}$.`, sol: 'Nine row-by-column sums for each product; keep the order of the factors.', scheme: [['AB correct', 2], ['BA correct', 1.5], ['AB ≠ BA stated with an entry', 0.5], ['AB − BA', 1]], d: 3, c: 'application', t: [2], time: 480 }), (C) => { const P = mul(A_l1, B_l1), Q2 = mul(B_l1, A_l1); C.assert(!eqM(P, Q2), 'differ'); C.model([bm(P), bm(Q2), bm(sub(P, Q2))]); });
const qty_l2 = [[30, 50, 20], [45, 25, 40]], price_l2 = [[900], [150], [1200]];
Q('l02', mk.long({ stem: r`A cricket-kit dealer in Meerut supplies two academies. Academy X orders $30$ bats, $50$ balls and $20$ pairs of pads; academy Y orders $45$ bats, $25$ balls and $40$ pairs of pads. A bat costs ₹$900$, a ball ₹$150$ and a pair of pads ₹$1200$.
(a) Write the orders as a $2 \times 3$ matrix $Q$ and the prices as a $3 \times 1$ matrix $P$. Explain why $QP$ is defined but $PQ$ is not.
(b) Find $QP$ and interpret it.
(c) Next season every price rises by $10\%$. Use a scalar multiple to find the new bill of each academy, and the total increase for both academies together.`, model: r`(a) $Q = \begin{bmatrix} 30 & 50 & 20 \\ 45 & 25 & 40 \end{bmatrix}$, $P = \begin{bmatrix} 900 \\ 150 \\ 1200 \end{bmatrix}$. $QP$: $Q$ has $3$ columns and $P$ has $3$ rows, so it is defined ($2 \times 1$). $PQ$: $P$ has $1$ column but $Q$ has $2$ rows, so it is not defined.
(b) $QP = \begin{bmatrix} 27000 + 7500 + 24000 \\ 40500 + 3750 + 48000 \end{bmatrix} = \begin{bmatrix} 58500 \\ 92250 \end{bmatrix}$: academy X's bill is ₹$58{,}500$ and academy Y's bill is ₹$92{,}250$.
(c) New prices $1.1P$, so the new bills are $Q(1.1P) = 1.1(QP) = \begin{bmatrix} 64350 \\ 101475 \end{bmatrix}$: ₹$64{,}350$ and ₹$1{,}01{,}475$.
Total before: ₹$1{,}50{,}750$; after: ₹$1{,}65{,}825$; increase ₹$15{,}075$ (which is $10\%$ of ₹$1{,}50{,}750$).`, sol: 'A scalar factor can be taken outside a product: Q(kP) = k(QP).', scheme: [['Q, P and the defined/undefined reasons', 1], ['QP computed', 1.5], ['Interpretation', 0.5], ['New bills via 1.1(QP)', 1], ['Total increase', 1]], d: 4, c: 'application', t: [1, 2], time: 540 }), (C) => {
  const B = mul(qty_l2, price_l2), B2 = mul(qty_l2, scal(1.1, price_l2));
  const tot = sum(B), tot2 = sum(B2);
  C.assert(Math.abs(tot2 - tot - 0.1 * tot) < 1e-6, 'increase 10%');
  C.model([B[0][0], B[1][0], Math.round(B2[0][0]), Math.round(B2[1][0]), tot, Math.round(tot2), Math.round(tot2 - tot)]);
});
const A_l3 = [[2, 4, -6], [0, 3, 5], [2, -1, 7]];
Q('l03', mk.long({ stem: r`Express $A = ${bm(A_l3)}$ as the sum of a symmetric matrix $P$ and a skew-symmetric matrix $Q$. Verify that $P$ is symmetric, $Q$ is skew-symmetric and $P + Q = A$.`, model: r`$A^T = \begin{bmatrix} 2 & 0 & 2 \\ 4 & 3 & -1 \\ -6 & 5 & 7 \end{bmatrix}$.
$A + A^T = \begin{bmatrix} 4 & 4 & -4 \\ 4 & 6 & 4 \\ -4 & 4 & 14 \end{bmatrix}$, so $P = \dfrac12(A + A^T) = \begin{bmatrix} 2 & 2 & -2 \\ 2 & 3 & 2 \\ -2 & 2 & 7 \end{bmatrix}$; $P^T = P$, so $P$ is symmetric.
$A - A^T = \begin{bmatrix} 0 & 4 & -8 \\ -4 & 0 & 6 \\ 8 & -6 & 0 \end{bmatrix}$, so $Q = \dfrac12(A - A^T) = \begin{bmatrix} 0 & 2 & -4 \\ -2 & 0 & 3 \\ 4 & -3 & 0 \end{bmatrix}$; $Q^T = -Q$, so $Q$ is skew-symmetric.
$P + Q = \begin{bmatrix} 2 & 4 & -6 \\ 0 & 3 & 5 \\ 2 & -1 & 7 \end{bmatrix} = A$.`, sol: 'P = ½(A + Aᵀ), Q = ½(A − Aᵀ); check each property.', scheme: [['Transpose', 1], ['P with symmetry check', 1.5], ['Q with skew check', 1.5], ['P + Q = A', 1]], d: 3, c: 'application', t: [3], time: 480 }), (C) => { const P = scal(0.5, add(A_l3, T(A_l3))), K = scal(0.5, sub(A_l3, T(A_l3))); C.assert(isSym(P) && isSkew(K) && eqM(add(P, K), A_l3), 'decomposition'); C.model([bm(T(A_l3)), bm(add(A_l3, T(A_l3))), bm(P), bm(sub(A_l3, T(A_l3))), bm(K), bm(A_l3)]); });
const A_l4 = [[3, -2], [6, 1]];
Q('l04', mk.long({ stem: r`(a) Prove that for any square matrix $A$, the matrix $A + A^T$ is symmetric and $A - A^T$ is skew-symmetric.
(b) Hence show that every square matrix can be written as the sum of a symmetric and a skew-symmetric matrix.
(c) Illustrate with $A = ${bm(A_l4)}$.`, model: r`(a) $(A + A^T)^T = A^T + (A^T)^T = A^T + A = A + A^T$, so $A + A^T$ is symmetric. $(A - A^T)^T = A^T - A = -(A - A^T)$, so $A - A^T$ is skew-symmetric.
(b) Multiplying by $\dfrac12$ keeps both properties, since $(kB)^T = kB^T$. Let $P = \dfrac12(A + A^T)$ and $Q = \dfrac12(A - A^T)$. Then $P$ is symmetric, $Q$ is skew-symmetric, and $P + Q = \dfrac12 A + \dfrac12 A^T + \dfrac12 A - \dfrac12 A^T = A$.
(c) $A^T = \begin{bmatrix} 3 & 6 \\ -2 & 1 \end{bmatrix}$; $P = \begin{bmatrix} 3 & 2 \\ 2 & 1 \end{bmatrix}$ and $Q = \begin{bmatrix} 0 & -4 \\ 4 & 0 \end{bmatrix}$. Check: $P + Q = \begin{bmatrix} 3 & -2 \\ 6 & 1 \end{bmatrix} = A$.`, sol: 'Transpose rules: (B + C)ᵀ = Bᵀ + Cᵀ, (kB)ᵀ = kBᵀ, (Aᵀ)ᵀ = A.', scheme: [['A + Aᵀ symmetric', 1], ['A − Aᵀ skew-symmetric', 1], ['P + Q = A in general', 1], ['P and Q for the example', 1.5], ['Check', 0.5]], d: 4, c: 'analysis', t: [3], time: 480 }), (C) => { const P = scal(0.5, add(A_l4, T(A_l4))), K = scal(0.5, sub(A_l4, T(A_l4))); C.assert(isSym(P) && isSkew(K) && eqM(add(P, K), A_l4), 'decomposition'); C.model([bm(T(A_l4)), bm(P), bm(K), bm(A_l4)]); });
const A_l5 = [[2, -1], [-1, 2]];
Q('l05', mk.long({ stem: r`Let $A = ${bm(A_l5)}$.
(a) Show that $A^2 - 4A + 3I = O$.
(b) Hence find $A^{-1}$.
(c) Verify your answer by multiplying $A$ and $A^{-1}$.`, model: r`(a) $A^2 = \begin{bmatrix} 4 + 1 & -2 - 2 \\ -2 - 2 & 1 + 4 \end{bmatrix} = \begin{bmatrix} 5 & -4 \\ -4 & 5 \end{bmatrix}$. $4A = \begin{bmatrix} 8 & -4 \\ -4 & 8 \end{bmatrix}$, $3I = \begin{bmatrix} 3 & 0 \\ 0 & 3 \end{bmatrix}$. So $A^2 - 4A + 3I = \begin{bmatrix} 5 - 8 + 3 & -4 + 4 + 0 \\ -4 + 4 + 0 & 5 - 8 + 3 \end{bmatrix} = O$.
(b) $3I = 4A - A^2 = A(4I - A)$, so $A \cdot \dfrac13(4I - A) = I$; similarly $\dfrac13(4I - A) \cdot A = I$. Hence
$A^{-1} = \dfrac13(4I - A) = \dfrac13\begin{bmatrix} 2 & 1 \\ 1 & 2 \end{bmatrix} = \begin{bmatrix} \frac{2}{3} & \frac{1}{3} \\ \frac{1}{3} & \frac{2}{3} \end{bmatrix}$.
(c) $AA^{-1} = \dfrac13\begin{bmatrix} 4 - 1 & 2 - 2 \\ -2 + 2 & -1 + 4 \end{bmatrix} = \dfrac13\begin{bmatrix} 3 & 0 \\ 0 & 3 \end{bmatrix} = I$.`, sol: 'Rearrange the relation so that I stands alone, then factor out A.', scheme: [['A² computed', 1], ['Relation verified', 1], ['Rearranged to A(4I − A) = 3I', 1], ['A⁻¹', 1], ['Verification', 1]], d: 4, c: 'application', t: [2, 4], time: 480 }), (C) => {
  C.assert(eqM(add(sub(mul(A_l5, A_l5), scal(4, A_l5)), scal(3, I(2))), O(2)), 'relation');
  const B = scal(1 / 3, sub(scal(4, I(2)), A_l5)); C.assert(isInverse(A_l5, B), 'inverse');
  C.model([bm(mul(A_l5, A_l5)), bm(B), bm(sub(scal(4, I(2)), A_l5))]);
});
const E = (a) => [[1, a], [0, 1]];
Q('l06', mk.long({ stem: r`For a real number $a$, let $E(a) = \begin{bmatrix} 1 & a \\ 0 & 1 \end{bmatrix}$.
(a) Prove that $E(a)E(b) = E(a + b)$ for all real $a$, $b$.
(b) Deduce that $E(a)E(b) = E(b)E(a)$, although matrix multiplication is not commutative in general.
(c) Show that $E(a)$ is invertible and find its inverse.
(d) Find $E(3)^5$ and the value of $n$ for which $E(2)^n = E(18)$.`, model: r`(a) $E(a)E(b) = \begin{bmatrix} 1 \cdot 1 + a \cdot 0 & 1 \cdot b + a \cdot 1 \\ 0 + 0 & 0 \cdot b + 1 \end{bmatrix} = \begin{bmatrix} 1 & a + b \\ 0 & 1 \end{bmatrix} = E(a + b)$.
(b) $E(a)E(b) = E(a + b) = E(b + a) = E(b)E(a)$, using (a) twice and $a + b = b + a$. These particular matrices commute even though matrices in general do not.
(c) $E(a)E(-a) = E(0) = I$ and $E(-a)E(a) = E(0) = I$, so $E(a)$ is invertible with $E(a)^{-1} = E(-a) = \begin{bmatrix} 1 & -a \\ 0 & 1 \end{bmatrix}$.
(d) By (a) repeatedly, $E(3)^5 = E(15) = \begin{bmatrix} 1 & 15 \\ 0 & 1 \end{bmatrix}$. Similarly $E(2)^n = E(2n) = E(18)$ gives $2n = 18$, $n = 9$.`, sol: 'Multiply the general matrices once; every later part follows from the rule E(a)E(b) = E(a + b).', scheme: [['(a) product computed', 1.5], ['(b) commuting argued', 1], ['(c) inverse E(−a) with both products', 1.5], ['(d) E(15) and n = 9', 1]], d: 5, c: 'analysis', t: [2, 4], time: 540 }), (C) => {
  for (const [a, b] of [[2, 5], [-3, 1.5], [0.25, -7]]) C.assert(eqM(mul(E(a), E(b)), E(a + b)) && eqM(mul(E(a), E(b)), mul(E(b), E(a))) && isInverse(E(a), E(-a)), `E rule for ${a}, ${b}`);
  C.assert(eqM(pow(E(3), 5), E(15)) && eqM(pow(E(2), 9), E(18)), 'powers');
  C.model([bm(E(15)), 'n = 9']);
});

// =============================================================== case-based
const S_c1 = [[60, 45, 30], [50, 70, 40]], P_c1 = [[15], [20], [25]], T_c1 = [[55, 50, 35], [45, 60, 50]];
caseQ('c01', {
  passage: r`Two school canteens in Pune, A and B, record Monday's sales of samosas, idlis and glasses of juice. Canteen A sold $60$ samosas, $45$ idlis and $30$ juices; canteen B sold $50$ samosas, $70$ idlis and $40$ juices. The sales matrix $S$ has the canteens as rows and the items as columns. Both canteens charge ₹$15$ for a samosa, ₹$20$ for an idli and ₹$25$ for a juice, written as the column matrix $P$. On Tuesday the sales matrix was $T = \begin{bmatrix} 55 & 50 & 35 \\ 45 & 60 & 50 \end{bmatrix}$.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $2 \times 3$. (b) $115$ idlis. (c) (i) $SP = \begin{bmatrix} 2550 \\ 3150 \end{bmatrix}$: A ₹$2550$, B ₹$3150$. Or (ii) $S + T = \begin{bmatrix} 115 & 95 & 65 \\ 95 & 130 & 90 \end{bmatrix}$; B sold more items ($315$ against $275$).`,
  sol: r`(a) $2$ canteens, $3$ items. (b) Column 2: $45 + 70 = 115$. (c) (i) A: $900 + 900 + 750 = 2550$; B: $750 + 1400 + 1000 = 3150$. (ii) Add corresponding entries; row sums of $S + T$ are $275$ and $315$.`,
  children: [
    child('a', mk.mcq({ stem: 'The order of the sales matrix S is', opts: [r`$2 \times 3$`, r`$3 \times 2$`, r`$6 \times 1$`, r`$3 \times 3$`], key: 'a', sol: 'Two rows (canteens) and three columns (items).', d: 1, c: 'recall', t: [1], time: 45 })),
    child('b', mk.num({ stem: 'How many idlis did the two canteens sell together on Monday?', value: 115, sol: r`Add the entries of column 2 of $S$: $45 + 70 = 115$.`, scheme: [['115', 1]], d: 1, c: 'understanding', t: [1], time: 45 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** Find $SP$ and state what its entries mean.`, model: r`$SP = \begin{bmatrix} 60(15) + 45(20) + 30(25) \\ 50(15) + 70(20) + 40(25) \end{bmatrix} = \begin{bmatrix} 2550 \\ 3150 \end{bmatrix}$. Monday's takings: canteen A ₹$2550$, canteen B ₹$3150$.`, sol: 'Row of S times the price column.', scheme: [['Products set up', 1], ['2550 and 3150 with meaning', 1]], d: 2, c: 'application', t: [2], time: 150 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Find $S + T$ and decide which canteen sold more items over the two days.`, model: r`$S + T = \begin{bmatrix} 115 & 95 & 65 \\ 95 & 130 & 90 \end{bmatrix}$. Row sums: A $115 + 95 + 65 = 275$, B $95 + 130 + 90 = 315$. Canteen B sold more items.`, sol: 'Add corresponding entries, then add along each row.', scheme: [['S + T', 1], ['Row sums and conclusion', 1]], d: 2, c: 'application', t: [2], time: 150 }),
    ]),
  ],
}, (C) => {
  C.child('a').which(['2x3', '3x2', '6x1', '3x3'], `${S_c1.length}x${S_c1[0].length}`);
  C.child('b').val(S_c1[0][1] + S_c1[1][1]);
  const SP = mul(S_c1, P_c1); C.child('c').model([bm(SP)]);
  const ST = add(S_c1, T_c1); C.child('cii').model([bm(ST), sum([ST[0]]), sum([ST[1]])]);
  C.model([SP[0][0], SP[1][0], sum([ST[0]]), sum([ST[1]])]);
});
const Q_c2 = [[200, 300], [150, 250]], P_c2 = [[64], [52]];
caseQ('c02', {
  passage: r`A dairy cooperative near Anand delivers full-cream and toned milk every morning to two cities. Surat receives $200$ litres of full-cream and $300$ litres of toned milk; Vadodara receives $150$ litres of full-cream and $250$ litres of toned milk. This is recorded as $Q = \begin{bmatrix} 200 & 300 \\ 150 & 250 \end{bmatrix}$ (rows: Surat, Vadodara; columns: full-cream, toned). The prices per litre are ₹$64$ (full-cream) and ₹$52$ (toned), written as $P = \begin{bmatrix} 64 \\ 52 \end{bmatrix}$.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $QP$. (b) ₹$28400$. (c) (i) New bills $\begin{bmatrix} 30400 \\ 24200 \end{bmatrix}$; increases ₹$2000$ and ₹$1600$. Or (ii) $7QP = \begin{bmatrix} 198800 \\ 158200 \end{bmatrix}$.`,
  sol: r`(a) $Q$ is $2 \times 2$ and $P$ is $2 \times 1$, so $QP$ is defined and gives one bill per city. (b) $200(64) + 300(52) = 12800 + 15600 = 28400$. (c) (i) $P + \begin{bmatrix} 4 \\ 4 \end{bmatrix} = \begin{bmatrix} 68 \\ 56 \end{bmatrix}$. (ii) A week is $7$ identical days.`,
  children: [
    child('a', mk.mcq({ stem: 'Which product gives the daily bill of each city as a column matrix?', opts: ['$QP$', '$PQ$', '$P^TP$', '$P^TQ^T$'], key: 'a', sol: r`$QP$ is $2 \times 1$: each row of $Q$ (a city's litres) times the price column. $PQ$ is not defined; $P^TP$ is $1 \times 1$; $P^TQ^T$ is a $1 \times 2$ row, not a column.`, d: 2, c: 'understanding', t: [2], time: 60 })),
    child('b', mk.num({ stem: "Find Surat's daily bill (in ₹).", value: 28400, unit: '₹', sol: r`Row 1 of $Q$ times $P$: $200 \times 64 + 300 \times 52 = 12800 + 15600 = 28400$.`, scheme: [['28400', 1]], d: 2, c: 'understanding', t: [2], time: 60 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** Both prices rise by ₹$4$ per litre. Find the new daily bill matrix and each city's increase.`, model: r`New price matrix $\begin{bmatrix} 68 \\ 56 \end{bmatrix}$. New bills: $\begin{bmatrix} 200(68) + 300(56) \\ 150(68) + 250(56) \end{bmatrix} = \begin{bmatrix} 13600 + 16800 \\ 10200 + 14000 \end{bmatrix} = \begin{bmatrix} 30400 \\ 24200 \end{bmatrix}$. Old bills $\begin{bmatrix} 28400 \\ 22600 \end{bmatrix}$, so Surat pays ₹$2000$ more and Vadodara ₹$1600$ more ($4$ times the litres each city receives).`, sol: 'Add 4 to each price, multiply again, subtract the old bills.', scheme: [['New bills', 1], ['Increases', 1]], d: 3, c: 'application', t: [2], time: 180 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Deliveries and prices stay the same for a week of $7$ days. Write the weekly bill matrix as a scalar multiple and evaluate it.`, model: r`Weekly bill $= 7(QP) = 7\begin{bmatrix} 28400 \\ 22600 \end{bmatrix} = \begin{bmatrix} 198800 \\ 158200 \end{bmatrix}$: Surat ₹$1{,}98{,}800$, Vadodara ₹$1{,}58{,}200$.`, sol: 'Multiply the daily bill matrix by 7.', scheme: [['QP found', 1], ['7QP', 1]], d: 2, c: 'application', t: [2], time: 150 }),
    ]),
  ],
}, (C) => {
  const ok = (f) => { try { const M = f(); return M[0].length === 1 && M.length === 2; } catch { return false; } };
  C.child('a').which([() => mul(Q_c2, P_c2), () => mul(P_c2, Q_c2), () => mul(T(P_c2), P_c2), () => mul(T(P_c2), T(Q_c2))].map(ok), true);
  const B = mul(Q_c2, P_c2); C.child('b').val(B[0][0]);
  const N = mul(Q_c2, add(P_c2, [[4], [4]])); C.child('c').model([bm(N), bm(B), N[0][0] - B[0][0], N[1][0] - B[1][0]]);
  C.child('cii').model([bm(scal(7, B))]);
  C.model([B[0][0], bm(N), N[0][0] - B[0][0], N[1][0] - B[1][0], bm(scal(7, B))]);
});
const M_c3 = [[0, 7, 4], [5, 0, 6], [2, 9, 0]];
caseQ('c03', {
  passage: r`A football coach in Kolkata records passes between three midfielders in a practice match as a matrix $M = [m_{ij}]$, where $m_{ij}$ is the number of passes from player $i$ to player $j$:
$$M = \begin{bmatrix} 0 & 7 & 4 \\ 5 & 0 & 6 \\ 2 & 9 & 0 \end{bmatrix}$$
So player 1 passed $7$ times to player 2, and received $5$ passes from player 2.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $5$. (b) $7.5$. (c) (i) $S = \begin{bmatrix} 0 & 6 & 3 \\ 6 & 0 & 7.5 \\ 3 & 7.5 & 0 \end{bmatrix}$, $K = \begin{bmatrix} 0 & 1 & 1 \\ -1 & 0 & -1.5 \\ -1 & 1.5 & 0 \end{bmatrix}$, $S + K = M$. Or (ii) $M - M^T = \begin{bmatrix} 0 & 2 & 2 \\ -2 & 0 & -3 \\ -2 & 3 & 0 \end{bmatrix}$: player 1 out-passed players 2 and 3 by $2$ each; player 3 out-passed player 2 by $3$.`,
  sol: r`(a) $(M^T)_{12} = m_{21}$. (b) $\dfrac12(m_{23} + m_{32}) = \dfrac12(6 + 9)$. (c) Use $S = \dfrac12(M + M^T)$, $K = \dfrac12(M - M^T)$.`,
  children: [
    child('a', mk.mcq({ stem: r`The element in row 1, column 2 of $M^T$ is`, opts: ['$5$', '$7$', '$4$', '$2$'], key: 'a', sol: r`Transposing swaps the indices: $(M^T)_{12} = m_{21} = 5$, the passes player 1 **received** from player 2.`, d: 2, c: 'understanding', t: [3], time: 45 })),
    child('b', mk.num({ stem: r`Find the element in row 2, column 3 of $S = \frac12(M + M^T)$.`, value: 7.5, sol: r`$\dfrac12(m_{23} + m_{32}) = \dfrac12(6 + 9) = 7.5$: the average number of passes between players 2 and 3 in each direction.`, scheme: [['7.5', 1]], d: 2, c: 'understanding', t: [3], time: 60 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** Write $S = \frac12(M + M^T)$ and $K = \frac12(M - M^T)$, and check that $S + K = M$.`, model: r`$M^T = \begin{bmatrix} 0 & 5 & 2 \\ 7 & 0 & 9 \\ 4 & 6 & 0 \end{bmatrix}$. $S = \begin{bmatrix} 0 & 6 & 3 \\ 6 & 0 & 7.5 \\ 3 & 7.5 & 0 \end{bmatrix}$ (symmetric), $K = \begin{bmatrix} 0 & 1 & 1 \\ -1 & 0 & -1.5 \\ -1 & 1.5 & 0 \end{bmatrix}$ (skew-symmetric). Adding gives $\begin{bmatrix} 0 & 7 & 4 \\ 5 & 0 & 6 \\ 2 & 9 & 0 \end{bmatrix} = M$.`, sol: 'Transpose first, then halve the sum and the difference.', scheme: [['S', 1], ['K and S + K = M', 1]], d: 3, c: 'application', t: [3], time: 180 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Find $M - M^T$, show that it is skew-symmetric, and use it to say which player made more passes in each pair.`, model: r`$M - M^T = \begin{bmatrix} 0 & 2 & 2 \\ -2 & 0 & -3 \\ -2 & 3 & 0 \end{bmatrix}$. Its transpose is its negative, so it is skew-symmetric. A positive entry in row $i$, column $j$ means player $i$ passed more to $j$ than $j$ passed back: player 1 made $2$ more passes than player 2 and $2$ more than player 3 in those pairs; player 3 made $3$ more than player 2.`, sol: 'Read the positive entries of the difference.', scheme: [['M − Mᵀ and skew check', 1], ['Interpretation', 1]], d: 3, c: 'analysis', t: [3], time: 180 }),
    ]),
  ],
}, (C) => {
  C.child('a').which([5, 7, 4, 2], T(M_c3)[0][1]);
  const S = scal(0.5, add(M_c3, T(M_c3))), K = scal(0.5, sub(M_c3, T(M_c3)));
  C.child('b').val(S[1][2]);
  const fmtd = (A) => bm(A).replace(/\\frac\{(\d+)\}\{2\}/g, (m, p) => String(p / 2));
  C.assert(isSym(S) && isSkew(K) && eqM(add(S, K), M_c3), 'decomposition');
  C.child('c').model([bm(T(M_c3)), fmtd(S), fmtd(K), bm(M_c3)]);
  const D = sub(M_c3, T(M_c3)); C.assert(isSkew(D), 'skew'); C.child('cii').model([bm(D)]);
  C.model([fmtd(S), fmtd(K), bm(D)]);
});
const E_c4 = [[2, 1], [3, 2]], D_c4 = [[2, -1], [-3, 2]];
caseQ('c04', {
  passage: r`Students of a coding club in Bhopal send secret two-letter messages. Each letter is replaced by its position in the alphabet (A = 1, B = 2, …, Z = 26), and a pair of letters is written as a column matrix $X$. The sender transmits $Y = EX$, where the encoding matrix is $E = \begin{bmatrix} 2 & 1 \\ 3 & 2 \end{bmatrix}$. The receiver recovers $X = DY$ using a decoding matrix $D$ with $DE = ED = I$.`,
  d: 4, c: 'application',
  model: r`(a) Option (a): $D = \begin{bmatrix} 2 & -1 \\ -3 & 2 \end{bmatrix}$. (b) $29$. (c) (i) $X = \begin{bmatrix} 8 \\ 9 \end{bmatrix}$, the message HI. Or (ii) $ED = DE = I$ shown by multiplication.`,
  sol: r`(a) Check each option by multiplying with $E$. (b) $GO$ is $\begin{bmatrix} 7 \\ 15 \end{bmatrix}$; first entry of $EX$ is $14 + 15$. (c) (i) $DY$ with $Y = \begin{bmatrix} 25 \\ 42 \end{bmatrix}$. (ii) Two products of $2 \times 2$ matrices.`,
  children: [
    child('a', mk.mcq({ stem: 'The decoding matrix D is', opts: [r`$\begin{bmatrix} 2 & -1 \\ -3 & 2 \end{bmatrix}$`, r`$\begin{bmatrix} 2 & 1 \\ 3 & 2 \end{bmatrix}$`, r`$\begin{bmatrix} -2 & 1 \\ 3 & -2 \end{bmatrix}$`, r`$\begin{bmatrix} 2 & -3 \\ -1 & 2 \end{bmatrix}$`], key: 'a', sol: r`$E\begin{bmatrix} 2 & -1 \\ -3 & 2 \end{bmatrix} = \begin{bmatrix} 4 - 3 & -2 + 2 \\ 6 - 6 & -3 + 4 \end{bmatrix} = I$. Option (c) gives $-I$ and option (d) is the transpose of the correct matrix, which does not work.`, d: 2, c: 'understanding', t: [4], time: 75 })),
    child('b', mk.num({ stem: r`The word GO is $X = \begin{bmatrix} 7 \\ 15 \end{bmatrix}$. Find the first entry of the transmitted matrix $Y = EX$.`, value: 29, sol: r`Row 1 of $E$ times $X$: $2(7) + 1(15) = 29$. (The second entry is $3(7) + 2(15) = 51$.)`, scheme: [['29', 1]], d: 2, c: 'understanding', t: [2], time: 60 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** The receiver gets $Y = \begin{bmatrix} 25 \\ 42 \end{bmatrix}$. Decode the message.`, model: r`$X = DY = \begin{bmatrix} 2(25) - 1(42) \\ -3(25) + 2(42) \end{bmatrix} = \begin{bmatrix} 50 - 42 \\ -75 + 84 \end{bmatrix} = \begin{bmatrix} 8 \\ 9 \end{bmatrix}$. Letters 8 and 9 are H and I: the message is HI.`, sol: 'Multiply by the decoding matrix, then convert numbers to letters.', scheme: [['DY computed', 1], ['Message HI', 1]], d: 3, c: 'application', t: [2, 4], time: 150 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Show that $ED = I$ and $DE = I$ for $D = \begin{bmatrix} 2 & -1 \\ -3 & 2 \end{bmatrix}$, so $D = E^{-1}$.`, model: r`$ED = \begin{bmatrix} 4 - 3 & -2 + 2 \\ 6 - 6 & -3 + 4 \end{bmatrix} = \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix}$ and $DE = \begin{bmatrix} 4 - 3 & 2 - 2 \\ -6 + 6 & -3 + 4 \end{bmatrix} = \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix}$. Both products are $I$, so $D = E^{-1}$.`, sol: 'Both orders of multiplication are needed.', scheme: [['ED = I', 1], ['DE = I and conclusion', 1]], d: 2, c: 'understanding', t: [4], time: 150 }),
    ]),
  ],
}, (C) => {
  C.child('a').which([[[2, -1], [-3, 2]], [[2, 1], [3, 2]], [[-2, 1], [3, -2]], [[2, -3], [-1, 2]]].map((B) => isInverse(E_c4, B)), true);
  C.child('b').val(mul(E_c4, [[7], [15]])[0][0]);
  C.child('b').sol([mul(E_c4, [[7], [15]])[1][0]]);
  const X = mul(D_c4, [[25], [42]]); C.assert(eqM(mul(E_c4, [[8], [9]]), [[25], [42]]), 'HI encodes to 25, 42');
  C.child('c').model([bm(X), 'HI']);
  C.child('cii').model([bm(I(2))]); C.assert(isInverse(E_c4, D_c4), 'D inverse');
  C.model([bm(D_c4), 29, 'HI']);
});
